CREATE TRIGGER KARDEX_TRAN_DET_BI FOR KARDEX_TRAN_DET ACTIVE BEFORE INSERT POSITION 0 AS
DECLARE VARIABLE tmp DECIMAL(18,0);
BEGIN
  IF (NEW.SERIE IS NULL) THEN
    NEW.SERIE = GEN_ID(GEN_KARDEX_TRAN_DET_ID, 1);
  ELSE
  BEGIN
    tmp = GEN_ID(GEN_KARDEX_TRAN_DET_ID, 0);
    if (tmp < new.SERIE) then
      tmp = GEN_ID(GEN_KARDEX_TRAN_DET_ID, new.SERIE-tmp);
  END
END
